"""Product-specific minimal presentation over the retained shared records."""
import html,json,re
E=lambda s:html.escape(str(s),quote=True)
def paragraphs(xs):return ''.join('<li>'+E(x)+'</li>' for x in xs)
def prepare(root,out,pages,records,intro,choose,write,shell):
 entry=(root/'content/agent-entry.md').read_text()
 # This lean Markdown renderer is only for the authored entry (no arbitrary input).
 def md(s):
  s=E(s)
  s=re.sub(r'\[([^\]]+)\]\(([^)]+)\)',r'<a href="\2">\1</a>',s)
  s=re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',s)
  s=re.sub(r'`([^`]+)`',r'<code>\1</code>',s)
  blocks=[];lis=[]
  for line in s.splitlines():
   if line.startswith('- '):lis.append('<li>'+line[2:]+'</li>');continue
   if lis:blocks.append('<ul>'+''.join(lis)+'</ul>');lis=[]
   if line.startswith('# '):blocks.append('<h1>'+line[2:]+'</h1>')
   elif line.startswith('## '):blocks.append('<h2>'+line[3:]+'</h2>')
   elif line:blocks.append('<p>'+line+'</p>')
  if lis:blocks.append('<ul>'+''.join(lis)+'</ul>')
  return ''.join(blocks)
 def page(title,body,path,page='utility',description=None):
  descriptions={'Tools and guidance for your stack':'Tools, architecture and working practices for your application. Bring your own agent to choose, build with or reconsider a stack.','For agents':'Read Stack Menu directly from your agent chat: context routing, stack selection, complete Markdown/JSON profiles and migration contracts.','Choose a stack':'Compare curated application stacks using product components, hard requirements, deployment constraints and current project context.','Plan a migration':'Evaluate keeping an existing stack or plan compatible replacement and staged coexistence with explicit contracts and rollback checks.','Sources and coverage':'Explore the 14 covered stacks and use cases, documentation sources, research freshness, licenses and qualification limits.','Contact':'Suggest a tool or correction for Stack Menu, or contact Optimum Tech about consulting.','Privacy':'Context routing, hosting, website analytics and email privacy information for Stack Menu.','Page not found':'This Stack Menu address has no guide. Return home or read the agent entry.'}
  props=shell(title,'<main id="main">'+body+'</main>',page=page)
  props['description']=description or descriptions.get(title,descriptions['Tools and guidance for your stack'])
  write(path,props)
 pages.clear()
 profile_links=''.join('<li><a href="'+d['guide_url']+'">'+E(d['title'])+'</a><p>'+E('; '.join(d['use_cases']))+'.</p></li>' for d in records.values())
 coverage={'schema_version':'1.0','profile_count':len(records),'core_guidance_checked_on':next(iter(records.values()))['research_freshness'].get('core_guidance_checked_on'),'scope':'Curated application component profiles, not exhaustive language coverage or integration-qualified distributions.','coverage_gaps':json.loads((root/'menu/inputs/research/catalogue.json').read_text())['coverage_gaps'],'profiles':[{k:d[k] for k in ['id','title','language','kind','ui','host','use_cases','guide_url','markdown_url','json_url']} for d in records.values()]}
 write('coverage.json',json.dumps(coverage,ensure_ascii=False,indent=2)+'\n')
 page('Tools and guidance for your stack','''<h1>Tools and guidance for your stack.</h1><p class="intro">Choose what fits your application. Then find the libraries, documentation and checks to build it well.</p><p>Bring your own agent. Give it your requirements and this address:</p><pre>Read https://stack.menu/llms.txt and use it for my application.</pre><p><a class="primary" href="/agents/">Start here for agents →</a></p><p class="muted">14 curated profiles for web apps, services, command-line tools and native mobile.</p><details id="stacks"><summary>Covered stacks and use cases</summary><ul>'''+profile_links+'</ul></details>', 'index.html','home')
 page('For agents',md(entry),'agents/index.html','agents')
 write('agents/guide.md',entry)
 write('agents/routing.md',(root/'content/routing.md').read_text())
 write('agents.md',entry)
 page('Choose a stack','<h1>Choose a stack from your requirements.</h1><p>Start with the product components, hard constraints and existing code. Compare feasible choices and resolve consequential unknowns before committing to an architecture.</p><p><a href="/choose.md">Complete selection workflow (Markdown)</a> · <a href="/selection-index.json">Compact selection index (JSON)</a></p><ul>'+profile_links+'</ul>','choose/index.html')
 page('Plan a migration','<h1>Reconsider an existing application.</h1><p>Start with what runs today. Compare keeping it with compatible replacement and staged coexistence. Inventory contracts, qualify each ownership transfer and rehearse rollback.</p><ul><li><a href="/rewrite/guide.md">Migration workflow</a></li><li><a href="/rewrite/contracts.json">Shared contracts and phases</a></li><li><a href="/rewrite/records.json">All stack-specific architecture and transition records</a></li></ul><p>Recipes are documentation-reviewed. Application compatibility and migration checks require actual evidence.</p>','rewrite/index.html')
 for d in records.values():
  body='<h1>'+E(d['title'])+'</h1><p class="intro">'+E(d['summary'])+'</p><p>'+E(d['shape'])+'</p><p><a href="'+d['markdown_url']+'">Complete guide (Markdown)</a> · <a href="'+d['json_url']+'">Structured record (JSON)</a></p><p class="muted">Original source review: '+d['reviewed']+'. Core guidance rechecked: '+d['research_freshness'].get('core_guidance_checked_on',d['reviewed'])+'. <a href="/research-freshness.json">Check scope</a>. Dependency combinations and setup need project-specific qualification.</p>'
  for title,xs in [('Use cases',d['use_cases']),('Choose it when',d['choose_when']),('Consider another path when',d['avoid_when']),('Working practices',d['best_practices'])]:body+='<h2>'+title+'</h2><ul>'+paragraphs(xs)+'</ul>'
  import generator_content
  body+=generator_content.profile_html(d['generators'],d['generators']['policy'])
  body+='<h2>Tools by job</h2>'
  for t in d['tools']:
   body+='<section><h3>'+E(t['job'])+': '+E(t['default'])+'</h3><p>'+E(t['reason'])+'</p><p>'+E(t['limits'])+'</p><ul>'+''.join('<li><a href="'+E(u)+'">'+E(u)+'</a></li>' for u in t.get('source_urls',[]))+'</ul></section>'
  import migration_content
  body+=migration_content.profile_html(d['architecture_and_migration'],json.loads((out/'rewrite/contracts.json').read_text())['contracts'])
  body+='<h2>Setup</h2><ol>'+paragraphs(d['setup_steps'])+'</ol><h2>Verification</h2><p>Run these in the configured application; they are instructions, not recorded passes.</p><pre>'+E('\n'.join(d['verification_commands']))+'</pre><h2>Open questions</h2><ul>'+paragraphs(d['open_questions'])+'</ul><h2>Sources</h2><ul>'+''.join('<li><a href="'+E(s['url'])+'">'+E(s.get('title',s['url']))+'</a></li>' for s in d['sources'])+'</ul>'
  if d.get('extended_reference'):body+='<h2>Extended Elixir reference</h2><p>The full Markdown and JSON include the attributed Elixir Menu optional libraries, runtime and other application paths. <a href="https://elixir.menu/">Read the maintained Elixir Menu reference</a>.</p>'
  page(d['title'],body,'stacks/'+d['id']+'/index.html','guide',description=d['summary'])
 page('Sources and coverage','<h1>Sources and coverage.</h1><p>Stack Menu is built for your own agent to read and use during an application conversation. This page describes the research available to it.</p><h2>Covered stacks and use cases</h2><ul>'+profile_links+'</ul><p><a href="/coverage.json">Coverage as JSON</a></p><p>Stack Menu is a reference for choosing an application stack and building with it. It provides 14 curated profiles with tool choices, generators, architecture, working practices and migration guidance.</p><p>The original tool research is dated 10 October 2026; architecture and transition research is dated 11 October. Core framework guidance and existing source availability were rechecked on 13 October. <a href="/research-freshness.json">Read the check scope and corrections</a>. Setup recipes, complete dependency combinations and application migrations need qualification in the actual project. There is no measured cross-stack ranking.</p><p>Generator and template guidance for all 14 profiles was documentation-reviewed on 18 October 2026. <a href="/generators.json">Read the generator records and required workflow</a>. Commands and templates have not been executed as part of that review.</p><p>Human pages, Markdown and JSON derive from the same records. The routing endpoint filters explicit requirements; the visiting agent reasons about the product.</p><p>Elixir Menu remains the original editorial owner of its extended reference. Copyright 2026 Optimum Tech, LLC, used under <a href="/menu-assets/elixir-LICENSE.txt">Apache 2.0</a>; <a href="/menu-assets/elixir-NOTICE.txt">original notice</a>. IBM Plex font licenses are retained with the files.</p><p><a href="/catalogue.json">Complete catalogue</a> · <a href="/llms-full.txt">Full agent bundle</a></p>','about/index.html')
 contact=json.loads((root/'content/contact.json').read_text())
 tools,consulting=contact['contactPoint'];address=contact['address']
 page('Contact','<h1>Contact.</h1><h2>Missed something?</h2><p>Suggest a tool or correction at <a href="mailto:'+E(tools['email'])+'">'+E(tools['email'])+'</a>. Include the relevant Stack Menu page and a link to the project or documentation that supports your suggestion.</p><h2>Work with Optimum Tech</h2><p>For consulting inquiries, email <a href="mailto:'+E(consulting['email'])+'">'+E(consulting['email'])+'</a> with a short description of your application and what you need help with.</p><p>Learn more about <a href="'+E(contact['url'])+'">'+E(contact['name'])+'</a>.</p><h2>Company mailing address</h2><address>'+E(contact['legalName'])+'<br />'+E(address['streetAddress'])+'<br />'+E(address['addressLocality'])+', '+E(address['addressRegion'])+' '+E(address['postalCode'])+'<br />United States</address><p class="muted">This is a mailing address, not a staffed office or visitor location. Please use email for website and project inquiries.</p><p class="muted"><a href="/contact.json">Contact details (JSON)</a></p>','contact/index.html')
 page('Privacy','<h1>Privacy.</h1><p>This notice covers the public website at stack.menu. Linked products and services have their own privacy notices.</p><h2>Reading and context routing</h2><p>You can read the guides without an account. The context router accepts structured requirement fields and returns guidance without saving them in an application database. Send only the fields it needs; omit private conversations, source code and credentials.</p><p>Your chosen agent has its own data handling. Use POST for context rather than putting sensitive information in a URL.</p><h2>Hosting and analytics</h2><p>Cloudflare Pages serves this website. Delivery and security providers receive the network information needed to respond to web requests. Read the <a href="https://www.cloudflare.com/privacypolicy/">Cloudflare privacy policy</a> for its processing practices.</p><p>The public HTML pages use Plausible for aggregate pageview analytics. Local and preview hostnames, missing pages and the context router do not load its tracker. Requirement fields, page query parameters and fragments are not sent to analytics. Read the <a href="https://plausible.io/data-policy">Plausible data policy</a> for its measurement and storage practices.</p><h2>Email</h2><p>Contact links open your email client. If you email us, your message and the contact details you provide are handled through the email service used for that conversation. Please do not send passwords, access tokens or unnecessary sensitive information.</p><p>For a question or correction to this notice, email <a href="mailto:'+E(consulting['email'])+'">'+E(consulting['email'])+'</a>.</p><p class="muted">Site configuration reviewed 13 October 2026.</p>','privacy/index.html')
 page('Page not found','<h1>That guide isn’t here.</h1><p><a href="/">Return home</a> or <a href="/agents/guide.md">read the agent entry</a>.</p>','404.html')
 write('llms.txt',entry+'\n## Profile directory\n\n'+'\n'.join('- ['+d['title']+']('+d['markdown_url']+'): '+d['summary']+' JSON: '+d['json_url'] for d in records.values())+'\n\n[Stack coverage and use cases](/coverage.json)\n')
 bundle=(out/'llms-full.txt').read_text();write('llms-full.txt',entry+'\n\n---\n\n'+bundle)
 # Runtime filtering uses the exact compact index also served to readers.
 (root/'lib/selection-index.json').write_text((out/'selection-index.json').read_text())
 for f in (root/'content').glob('*.json'):write(f.name,f.read_text())
